{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C10", "C15", "C24", "C03", "C13", "C01", "C04", "C26", "C25", "C41", "C36", "C37", "C47", "C78", "C70", "C81", "C73", "C95"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C10", "C15", "C24", "C03", "C13", "C01", "C04", "C26", "C25"],
  "claims": [
    {
      "claim": "Cladribine, the closest 2-halogenated adenine nucleoside analog, had absolute oral bioavailability of 36–46% in fasted patients, directly supporting F ≥20% for the 2-fluoroadenine nucleoside query.",
      "card_ids": ["C10", "C15", "C24"]
    },
    {
      "claim": "Didanosine, a purine nucleoside with relatively low fasted F (22–28%), still exceeded the 20% threshold, showing that even poorly absorbed purine nucleosides can meet the endpoint.",
      "card_ids": ["C03", "C13"]
    },
    {
      "claim": "Polar pyrimidine nucleosides lamivudine and emtricitabine had high fasted oral bioavailability (69–95% and 92%), demonstrating that high polarity does not preclude F ≥20%.",
      "card_ids": ["C01", "C04", "C26"]
    },
    {
      "claim": "Zalcitabine absolute oral bioavailability was 80% in fasted patients and 30% in fasted mice, both above the threshold.",
      "card_ids": ["C25", "C41"]
    },
    {
      "claim": "L3 oral exposure records for nucleoside analogs (e.g., penciclovir after oral famciclovir, didanosine, emtricitabine) show measurable oral AUC/Cmax, consistent with oral absorption of polar nucleosides, though they are not direct F measurements for the query.",
      "card_ids": ["C70", "C81", "C78", "C73", "C95"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C78", "C70", "C81", "C94", "C98", "C73", "C95", "C49", "C76", "C88", "C82", "C96"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule itself.",
    "L3 records provide oral AUC/Cmax but not absolute F with an IV comparator for the query or its closest analog.",
    "The query is a pyranose nucleoside, whereas most supporting records are furanose or oxathiolane nucleosides, so structural transferability is moderate rather than exact.",
    "No direct permeability, transporter, intestinal metabolism, or first-pass extraction data are available for the query.",
    "Some supporting records are from mice rather than humans, adding species uncertainty."
  ],
  "decision_summary": "The query is a polar 2-fluoroadenine nucleoside. The closest analog cladribine (36–46%) and other nucleoside analogs (didanosine 22–28%, lamivudine 69–95%, emtricitabine 92%, zalcitabine 30–80%) all show absolute oral bioavailability ≥20%. L3 oral exposure records for nucleoside analogs are consistent with oral absorption and do not provide affirmative evidence for F <20%. The better-supported prediction is high, with moderate confidence."
}

